#!/bin/sh
# generate-dev-keys.sh — DEV-ONLY age identities for the compose backup loop.
#
# SEC-11: real restore keys are generated by the two restore operators
# themselves (age-keygen on their own machines) and NEVER enter git, CI or
# the cluster. This script exists only so the local compose rehearsal loop
# (docs/ops/backup-restore.md) can exercise dual-authorisation end to end.
# The generated files are gitignored and marked DEV-ONLY inside the file.
set -eu

DIR=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)

for who in inner outer; do
    out="$DIR/$who.agekey"
    if [ -f "$DIR/$who.agekey" ]; then
        echo "keeping existing $who.agekey"
    else
        { echo "# DEV-ONLY — local compose rehearsal key, never use outside docker compose"; \
          age-keygen; } > "$DIR/$who.agekey.tmp.$$"
        mv "$DIR/$who.agekey.tmp.$$" "$DIR/$who.agekey"
        echo "generated $who.agekey (DEV-ONLY)"
    fi
done

echo
echo "Public recipients for compose (already committed as DEV-ONLY values):"
grep -h '^# public key:' "$DIR"/*.agekey || true
